#include "rmp_dwin.h"
#include "rmp_pins.h"
#include "rmp_config.h"
#include <math.h>
#include <stdio.h>
#include <string.h>
#include "driver/uart.h"
#include "freertos/FreeRTOS.h"
#include "freertos/semphr.h"
#include "esp_log.h"
namespace rmp {
namespace { constexpr char kTag[]="rmp_dwin"; constexpr uart_port_t kUart=UART_NUM_1; }
void Dwin::begin(){if(!mutex_)mutex_=xSemaphoreCreateMutex();uart_config_t c={};c.baud_rate=DWIN_BAUD;c.data_bits=UART_DATA_8_BITS;c.parity=UART_PARITY_DISABLE;c.stop_bits=UART_STOP_BITS_1;c.flow_ctrl=UART_HW_FLOWCTRL_DISABLE;c.source_clk=UART_SCLK_DEFAULT;uart_driver_install(kUart,512,512,0,nullptr,0);uart_param_config(kUart,&c);uart_set_pin(kUart,PIN_DWIN_TX,PIN_DWIN_RX,UART_PIN_NO_CHANGE,UART_PIN_NO_CHANGE);ESP_LOGI(kTag,"DWIN v3 UART initialized at %d baud (TX=%d RX=%d)",DWIN_BAUD,PIN_DWIN_TX,PIN_DWIN_RX);}
void Dwin::lock(){if(mutex_)xSemaphoreTake((SemaphoreHandle_t)mutex_,portMAX_DELAY);}void Dwin::unlock(){if(mutex_)xSemaphoreGive((SemaphoreHandle_t)mutex_);}
void Dwin::sendRaw(const uint8_t*d,size_t n){lock();uart_write_bytes(kUart,d,n);unlock();vTaskDelay(pdMS_TO_TICKS(5));}
void Dwin::pollRx(){size_t a=0;uart_get_buffered_data_len(kUart,&a);if(!a)return;uint8_t b[64];int n=uart_read_bytes(kUart,b,sizeof(b),0);if(n>=9&&b[0]==0x5A&&b[1]==0xA5&&b[3]==0x83&&b[4]==0&&b[5]==0x14&&b[6]==1)current_page_=b[8];}
void Dwin::readPageRequest(){const uint8_t f[]={0x5A,0xA5,0x04,0x83,0x00,0x14,0x01};sendRaw(f,sizeof(f));}
void Dwin::setPage(uint8_t p){current_page_=p;const uint8_t f[]={0x5A,0xA5,0x07,0x82,0x00,0x84,0x5A,0x01,0x00,p};sendRaw(f,sizeof(f));}
void Dwin::writeValue(uint16_t vp,uint16_t v){const uint8_t f[]={0x5A,0xA5,0x05,0x82,(uint8_t)(vp>>8),(uint8_t)vp,(uint8_t)(v>>8),(uint8_t)v};sendRaw(f,sizeof(f));}
void Dwin::writeText(uint16_t vp,const char*s,size_t max){if(!s)s="";uint8_t f[128];size_t n=6,cnt=0;f[0]=0x5A;f[1]=0xA5;f[2]=0;f[3]=0x82;f[4]=(uint8_t)(vp>>8);f[5]=(uint8_t)vp;for(size_t i=0;s[i]&&i<max&&n<sizeof(f)-4;i++){char c=s[i];f[n++]=(c>=0x20&&c<=0x7E)?(uint8_t)c:(uint8_t)' ';cnt++;}if(cnt&1)f[n++]=0;f[n++]=0xFF;f[n++]=0xFF;f[2]=(uint8_t)(n-3);sendRaw(f,n);}
void Dwin::writeNavigationState(uint16_t focus,uint16_t top,uint16_t diagFocus,uint16_t assignmentState){(void)assignmentState;if(current_page_==DWIN_PAGE_ASSIGNMENT){writeValue(VP_BTN_ACCEPT,focus==0?1:0);writeValue(VP_BTN_REJECT,focus==1?1:0);return;}if(current_page_==DWIN_PAGE_PRESTART){writeValue(VP_BTN_START,focus==0?1:0);writeValue(VP_BTN_CANCEL,focus==1?1:0);return;}if(current_page_!=DWIN_PAGE_DIAGNOSTICS)return;diagnostics_window_top_=(top>2)?2:(uint8_t)top;uint16_t rf=diagFocus<=4?diagFocus:99;for(uint8_t i=0;i<5;i++)writeValue((uint16_t)(VP_DIAG_ROW_BASE+i),i==rf?1:0);writeValue(VP_DIAG_SCROLL,diagnostics_window_top_);writeValue(VP_BTN_RETURN,diagFocus==5?1:0);}
void Dwin::writePowerUpDefaults(){writeValue(VP_TEMP_QUAL_PILL,2);writeValue(VP_RUN_FOOTER,0);writeValue(VP_ALARM_FLASH,0);writeValue(VP_MUTE_BUTTON,0);writeValue(VP_AUDIT_STATE,0);writeValue(VP_BOOT_PROGRESS,0);for(uint8_t i=0;i<5;i++){writeValue((uint16_t)(VP_DIAG_DOT_BASE+i),DOT_OFF);writeValue((uint16_t)(VP_DIAG_ROW_BASE+i),0);}writeValue(VP_DIAG_SCROLL,0);writeValue(VP_BTN_RETURN,0);}
void Dwin::showBootPage(uint8_t p,const char*fw){if(fw)writeText(VP_FW_VERSION,fw,16);writeValue(VP_BOOT_PROGRESS,p>100?100:p);}
void Dwin::showIdlePage(const char*reactor,const char*lab,const char*clock,bool online,uint16_t q,float t,float raw,bool tok,float rpm,float tq,bool motor,const char*cal){(void)clock;(void)online;(void)q;(void)t;(void)raw;(void)tok;(void)rpm;(void)tq;(void)motor;(void)cal;if(lab)writeText(VP_LAB_NAME,lab,14);if(reactor)writeText(VP_REACTOR_TITLE,reactor,14);writeText(VP_ANALYST_NAME,"Unassigned",17);writeText(VP_PROCESS_NAME,"Process Unassigned",22);}
void Dwin::showUnboundPage(const char*uuid,const char*mac,const char*ip,const char*broker){if(uuid)writeText(VP_DEVICE_UUID,uuid,22);if(mac)writeText(VP_MAC_ADDRESS,mac,22);if(ip)writeText(VP_IP_ADDRESS,ip,22);if(broker)writeText(VP_MQTT_BROKER,broker,22);}
void Dwin::showAssignmentPage(const char*analyst,const char*lab,const char*reactor,const char*process){if(lab)writeText(VP_LAB_NAME,lab,14);if(reactor)writeText(VP_REACTOR_TITLE,reactor,14);if(analyst)writeText(VP_ANALYST_NAME,analyst,17);if(process)writeText(VP_PROCESS_NAME,process,22);}
void Dwin::showPreStartPage(const char*analyst,const char*lab,const char*reactor,const char*process,float mt,float ms,float mr){showAssignmentPage(analyst,lab,reactor,process);char b[20];snprintf(b,sizeof(b),"%.1f",mt);writeText(VP_MAX_TEMP,b,5);snprintf(b,sizeof(b),"%d",(int)lroundf(ms));writeText(VP_MAX_SPEED,b,5);snprintf(b,sizeof(b),"%+.1f",mr);writeText(VP_MAX_ROC,b,5);}
void Dwin::showRunningPage(const char*reactor,const char*lab,const char*analyst,const char*process,const char*clock,bool online,uint16_t q,float t,float raw,bool tok,float rpm,float rpmSet,float tq,uint8_t torque,bool motor,float trend,const char*batch,const char*dur,uint8_t fault,bool silenced,const char*cal){(void)online;(void)raw;(void)rpmSet;(void)torque;(void)trend;(void)batch;(void)fault;(void)cal;showAssignmentPage(analyst,lab,reactor,process);if(clock)writeText(VP_CLOCK,clock,5);writeValue(VP_TEMP_QUAL_PILL,q<=2?q:2);char b[20];if(tok&&isfinite(t))snprintf(b,sizeof(b),"%.1f",t);else snprintf(b,sizeof(b),"---");writeText(VP_TEMP_VALUE,b,6);if(motor&&isfinite(rpm))snprintf(b,sizeof(b),"%d",(int)lroundf(rpm));else snprintf(b,sizeof(b),"---");writeText(VP_RPM_VALUE,b,6);if(motor&&isfinite(tq))snprintf(b,sizeof(b),"%.1f",tq);else snprintf(b,sizeof(b),"---");writeText(VP_TORQUE_VALUE,b,6);if(dur)writeText(VP_DURATION,dur,8);writeValue(VP_RUN_FOOTER,silenced?1:0);}
void Dwin::showAlarmPage(const char*param,float rate,float limit,float temp,bool muted,bool dim){if(param)writeText(VP_ALARM_PARAM,param,22);char b[20];snprintf(b,sizeof(b),isfinite(rate)?"%+.1f":"---",rate);writeText(VP_ALARM_RATE,b,7);snprintf(b,sizeof(b),isfinite(limit)?"%+.1f":"---",limit);writeText(VP_ALARM_LIMIT,b,6);snprintf(b,sizeof(b),isfinite(temp)?"%.1f":"---",temp);writeText(VP_ALARM_TEMP,b,6);writeValue(VP_MUTE_BUTTON,muted?1:0);writeValue(VP_ALARM_FLASH,dim?1:0);}
void Dwin::showBatchCompletedPage(const char*process,const char*lab,const char*reactor,const char*analyst,const char*duration,float temp,uint32_t samples,bool stored){showAssignmentPage(analyst,lab,reactor,process);if(duration)writeText(VP_TOTAL_DURATION,duration,8);char b[20];snprintf(b,sizeof(b),isfinite(temp)?"%.1f":"---",temp);writeText(VP_FINAL_TEMP,b,8);snprintf(b,sizeof(b),"%lu",(unsigned long)samples);writeText(VP_SAMPLES_LOGGED,b,8);writeValue(VP_AUDIT_STATE,stored?1:0);}
void Dwin::showDiagnosticsPage(const char*ssid,DotStatus ds,const char*ip,DotStatus di,const char*mqtt,DotStatus dm,const char*mtls,DotStatus dmtls,const char*ntp,DotStatus dntp,const char*rtd,DotStatus drtd,const char*rs232,DotStatus drs,const char*flash,DotStatus df,const char*mac,DotStatus dmac){(void)ntp;(void)dntp;(void)flash;(void)df;const char*names[]={"SSID","IP","MQTT","mTLS","RTD","RS232","MAC"};const char*vals[]={ssid,ip,mqtt,mtls,rtd,rs232,mac};DotStatus dots[]={ds,di,dm,dmtls,drtd,drs,dmac};for(uint8_t s=0;s<5;s++){uint8_t i=diagnostics_window_top_+s;if(i>6)break;writeText((uint16_t)(VP_DIAG_CAPTION_BASE+s*0x10),names[i],8);writeText((uint16_t)(VP_DIAG_VALUE_BASE+s*0x10),vals[i]?vals[i]:"--",21);writeValue((uint16_t)(VP_DIAG_DOT_BASE+s),dots[i]);}}
}
